'use strict';
const v272Init=Router.init.bind(Router);Router.init=async function(){const r=await v272Init();for(const e of document.querySelectorAll('.top-actions a[href="#field"],#business-menu,#audit-nav'))e.remove();const nav=document.querySelector('.sidebar nav'),report=nav.querySelector('[data-primary-route=reports]'),map=nav.querySelector('[data-primary-route="stock-map"]');if(report&&map)map.after(report);return r;};
V27.customerTable=function(sort='customer_name'){const body=$('v27-customer-rows');if(!body)return;const rows=[...this.mapRows].sort((a,b)=>sort==='customer_name'?a.customer_name.localeCompare(b.customer_name):Tonnes.scaled(b[sort]||'0',6)>Tonnes.scaled(a[sort]||'0',6)?1:-1),row=(x,label)=>`<tr><td>${label}</td><td>${x.active_lots}</td><td>${x.bundles}</td><td>${Tonnes.format(x.locked_net_weight)}</td><td>${Tonnes.format(x.loaded_net_weight)}</td><td>${Tonnes.format(x.total_net_weight)}${x.unknown_bundles?'<br>'+x.unknown_bundles+' <span>捆未完成检斤</span>':''}</td></tr>`,head='<colgroup><col style="width:24%"><col style="width:9%"><col style="width:9%"><col style="width:19%"><col style="width:19%"><col style="width:20%"></colgroup><thead><tr><th>客户 / 月份 / 批次</th><th>批次数</th><th>捆数</th><th>备货锁定净重（吨）</th><th>已装车待出库净重（吨）</th><th>当前备货合计净重（吨）</th></tr></thead>';body.innerHTML=rows.map(c=>`<details class="preparation-tree"><summary><span data-no-i18n>${esc(c.customer_name)}</span> · ${c.active_lots} <span>备货批次</span> · ${c.bundles} <span>捆</span> · ${Tonnes.format(c.total_net_weight)} <span>吨</span></summary><div class="business-table"><table>${head}<tbody>${row(c,'<span>客户备货统计</span>')}</tbody></table></div>${(c.months||[]).map(m=>`<details class="preparation-tree"><summary><span ${m.month==='UNKNOWN'?'':'data-no-i18n'}>${m.month==='UNKNOWN'?'月份待确认':esc(m.month)}</span> · ${m.active_lots} <span>备货批次</span> · ${m.bundles} <span>捆</span></summary><div class="business-table"><table>${head}<tbody>${row(m,'<span>发运月份</span>')}${m.lots.map(l=>row(l,`<a data-no-i18n href="/preparation/${l.id}">${esc(l.lot_no||'—')}</a>`)).join('')}</tbody></table></div></details>`).join('')}</details>`).join('')||'<p>当前授权范围无活跃备货</p>';I18n.apply();};
V27.preparationSummary=async function(){const section=document.createElement('section');section.className='panel preparation-summary';section.innerHTML='<h2>客户备货统计</h2><div class="preparation-kpis" id="preparation-kpis"></div><div id="v27-customer-rows" aria-live="polite"></div>';$('page-content').prepend(section);try{const data=await API.request('/preparation/summary');this.mapRows=data.items;const sum=key=>this.mapRows.reduce((n,r)=>n+Number(r[key]||0),0),known=this.mapRows.filter(r=>r.total_net_weight!=null),total=known.reduce((n,r)=>n+Tonnes.scaled(r.total_net_weight,6),0n),weight=known.length||!this.mapRows.length?Tonnes.format((total/1000000n)+'.'+String(total%1000000n).padStart(6,'0')):'—',unknown=sum('unknown_bundles');$('preparation-kpis').innerHTML=[['客户数量',this.mapRows.length],['备货批次',sum('active_lots')],['捆数',sum('bundles')],['当前备货合计净重（吨）',weight]].map(([label,value])=>'<article><span>'+label+'</span><strong data-no-i18n>'+value+'</strong></article>').join('')+(unknown?'<p>'+unknown+' <span>捆未完成检斤</span></p>':'');this.customerTable();}catch(e){$('v27-customer-rows').textContent=e.message;}I18n.apply();};
const v272Allocations=Business.allocations.bind(Business);Business.allocations=async function(...args){await v272Allocations(...args);await V27.preparationSummary();};

const v272Select=StockMap.select.bind(StockMap);StockMap.select=async function(...args){await v272Select(...args);const detail=$('stock-map-detail');if(document.fullscreenElement===MapView.stage&&detail)MapView.stage.append(detail);};document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){const d=$('stock-map-detail');if(d&&d.parentElement===MapView.stage)document.querySelector('.stock-map-layout')?.append(d);}});
